<script>
document.addEventListener('DOMContentLoaded', function () {
    var form = document.querySelector('[data-hierarchy-member-form]');
    if (!form) return;
    var list = form.querySelector('[data-hierarchy-member-list]');
    var template = document.getElementById('hierarchy-member-template');
    var add = form.querySelector('[data-hierarchy-member-add]');
    function renumber() {
        Array.prototype.forEach.call(list.querySelectorAll('[data-hierarchy-member-row]'), function (row, index) {
            var input = row.querySelector('[data-employee-autocomplete]');
            var hidden = row.querySelector('[data-hierarchy-member]');
            var label = row.querySelector('[data-member-label]') || row.querySelector('.parameter-option-mobile-label');
            var id = 'hierarchy-member-' + index;
            var inputId = id + '-search', hiddenId = id + '-id', listId = id + '-listbox';
            input.id = inputId; input.setAttribute('data-employee-id-target', hiddenId); input.setAttribute('aria-controls', listId);
            hidden.name = 'members[' + index + '][employee_id]'; hidden.id = hiddenId;
            var jobTitle = row.querySelector('[data-member-job-title]') || row.querySelector('input[name$="[job_title]"]');
            if (jobTitle) { jobTitle.name = 'members[' + index + '][job_title]'; jobTitle.id = id + '-job-title'; var jobLabel = row.querySelector('[data-job-title-label]'); if (jobLabel) jobLabel.htmlFor = jobTitle.id; }
            row.querySelector('[data-employee-listbox]').id = listId;
            if (label) label.htmlFor = inputId;
        });
    }
    add.addEventListener('click', function () {
        var row = template.content.firstElementChild.cloneNode(true);
        list.appendChild(row); renumber(); row.querySelector('[data-employee-autocomplete]').focus();
    });
    list.addEventListener('click', function (event) {
        var remove = event.target.closest('[data-hierarchy-member-remove]');
        if (!remove) return;
        var rows = list.querySelectorAll('[data-hierarchy-member-row]');
        if (rows.length <= 1) { rows[0].querySelector('[data-employee-autocomplete]').value = ''; rows[0].querySelector('[data-hierarchy-member]').value = ''; }
        else remove.closest('[data-hierarchy-member-row]').remove();
        renumber();
    });
    form.addEventListener('submit', function (event) {
        var seen = Object.create(null);
        var duplicateInput = null;
        Array.prototype.forEach.call(list.querySelectorAll('[data-hierarchy-member-row]'), function (row) {
            var input = row.querySelector('[data-employee-autocomplete]');
            var hidden = row.querySelector('[data-hierarchy-member]');
            var status = row.querySelector('[data-employee-status]');
            var employeeId = hidden.value;
            input.removeAttribute('aria-invalid');
            if (status && status.textContent === form.dataset.duplicateInlineLabel) status.textContent = '';
            if (!employeeId) return;
            if (seen[employeeId]) {
                input.setAttribute('aria-invalid', 'true');
                if (status) status.textContent = form.dataset.duplicateInlineLabel;
                if (!duplicateInput) duplicateInput = input;
            }
            seen[employeeId] = true;
        });
        if (duplicateInput) {
            event.preventDefault();
            duplicateInput.focus();
        }
    });
    renumber();
});
</script>
